(function(global){'use strict';
const forbidden=/(javascript:|<script|eval\s*\(|new\s+Function|data:text\/html|expression\s*\()/i;
function safeObject(v,depth=0){if(depth>12)throw new Error('visual metadata depth exceeded');if(Array.isArray(v))return v.map(x=>typeof x==='object'&&x?safeObject(x,depth+1):x);if(!v||typeof v!=='object')return v;const out={};for(const [k,x] of Object.entries(v)){if(['script','javascript','html','css','eval','sql','credentials','token','secret','rawurl','raw_url'].includes(k.toLowerCase()))throw new Error('forbidden visual metadata key');if(typeof x==='string'&&forbidden.test(x))throw new Error('executable visual payload rejected');out[k]=typeof x==='object'&&x?safeObject(x,depth+1):x;}return out;}
function env(){const m=global.matchMedia;return {reducedMotion:!!m&&m('(prefers-reduced-motion: reduce)').matches,highContrast:!!m&&m('(prefers-contrast: more)').matches,dpr:global.devicePixelRatio||1,width:global.innerWidth||0,webgl:(()=>{try{return !!document.createElement('canvas').getContext('webgl2')}catch(e){return false}})()};}
function apply(el,plan){if(!(el instanceof Element))throw new TypeError('Element required');const p=safeObject(plan);el.dataset.visualTreatment=String(p.visualTreatment||'default');el.dataset.motionPreset=String(p.motionPreset||'none');el.dataset.transitionPreset=String(p.transitionPreset||'none');el.dataset.visualStrategy=String(p.strategy||'fallback');return el;}
global.TitanVisualRuntime=Object.freeze({environment:env,apply,validate:safeObject});})(window);
